import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestButton } from "../components/auditRequestModal";
import { trackEvent } from "../utils/analytics";
import {
  livePortfolioImageMap,
  projectRelatedServiceKeys,
  type LivePortfolioProject,
} from "../utils/livePortfolio";
import { getLocaleValue } from "../utils/localeValue";

type PageContext = {
  imageKey: keyof typeof livePortfolioImageMap;
  slug: string;
  language: string;
};

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
      {children}
    </p>
  );
}

export default function CaseStudyPage({ pageContext }: { pageContext: PageContext }) {
  const { t } = useTranslation();
  const { language } = useI18next();
  const { imageKey } = pageContext;

  const liveProjects = (t("portfolio.live.items", { returnObjects: true }) as LivePortfolioProject[]) || [];
  const project = liveProjects.find((p) => p.imageKey === imageKey);
  const images = livePortfolioImageMap[imageKey];

  const servicesItems = (t("services.items", { returnObjects: true }) as Array<{
    key: string;
    title: string;
    href: string;
  }>) || [];

  const relatedServices = (projectRelatedServiceKeys[imageKey] || [])
    .map((serviceKey) => servicesItems.find((item) => item.key === serviceKey))
    .filter((item): item is { key: string; title: string; href: string } => Boolean(item));

  const portfolioPath = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";

  if (!project || !images) {
    return (
      <Layout data={info}>
        <main className="w-full min-h-screen bg-primary text-accent">
          <div className="px-4 py-20 text-center">
            <p className="text-neutral">{t("caseStudy.back")}</p>
          </div>
        </main>
      </Layout>
    );
  }

  const designImage = "design" in images ? (images.design as { src: string; alt?: string } | undefined) : undefined;

  return (
    <Layout data={info}>
      <main className="w-full min-h-screen bg-primary text-accent">

        {/* Breadcrumb */}
        <div className="w-full border-b border-neutral/10 bg-secondary/60">
          <div className="w-full px-4 sm:px-8 lg:px-12 py-3">
            <nav aria-label="breadcrumb" className="flex items-center gap-2 text-xs text-neutral">
              <Link to={portfolioPath} className="hover:text-accent transition-colors">
                {t("menu.portfolio")}
              </Link>
              <span aria-hidden="true">/</span>
              <span className="text-accent">{project.title}</span>
            </nav>
          </div>
        </div>

        {/* Hero */}
        <section className="relative overflow-hidden border-b border-neutral/20 bg-[radial-gradient(circle_at_top_left,_rgba(255,255,255,0.6),_transparent_38%),linear-gradient(135deg,_rgba(255,240,224,0.92),_rgba(249,249,249,0.96))] py-14 sm:py-18">
          <div className="w-full px-4 sm:px-8 lg:px-12">
            <Link
              to={portfolioPath}
              className="inline-flex items-center text-xs font-medium text-neutral hover:text-accent transition-colors mb-6"
            >
              {t("caseStudy.back")}
            </Link>
            <div className="grid gap-6 lg:grid-cols-12">
              <div className="lg:col-span-8">
                <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
                  Case Study
                </p>
                <h1 className="mt-3 text-3xl font-semibold tracking-tight text-accent sm:text-5xl">
                  {project.title}
                </h1>
                <p className="mt-3 text-base text-neutral">
                  <span className="font-medium text-accent">{project.role}</span>
                  {" · "}
                  <span>{project.stack}</span>
                </p>
                {project.note ? (
                  <p className="mt-4 max-w-2xl text-base leading-7 text-neutral">{project.note}</p>
                ) : null}
              </div>
              <div className="lg:col-span-4 flex items-start">
                <img
                  src={images.logo.src}
                  alt={images.logo.alt || `${project.title} logo`}
                  className="h-14 w-auto"
                  decoding="async"
                  width={280}
                  height={112}
                />
              </div>
            </div>
          </div>
        </section>

        {/* Hero image — live site screenshot */}
        <div className="w-full border-b border-neutral/20">
          <img
            src={images.large.src}
            alt={images.large.alt || project.title}
            className="w-full object-cover max-h-[540px]"
            decoding="async"
            width={1600}
            height={900}
          />
        </div>

        <div className="w-full px-4 sm:px-8 lg:px-12 py-14 space-y-14">

          {/* Use Case */}
          {project.useCase ? (
            <section>
              <SectionLabel>{t("selectedProjects.labels.useCase")}</SectionLabel>
              <p className="mt-4 max-w-3xl text-base leading-7 text-neutral">
                {project.useCase.summary}
              </p>

              {/* Figma design image */}
              {designImage ? (
                <div className="mt-8 overflow-hidden rounded-2xl border border-neutral/20 shadow-sm">
                  <div className="border-b border-neutral/10 bg-secondary/80 px-4 py-2 flex items-center gap-2">
                    <span className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
                      {t("caseStudy.design")}
                    </span>
                    <span className="text-xs text-neutral/60">· Figma</span>
                  </div>
                  <img
                    src={designImage.src}
                    alt={designImage.alt || `${project.title} — Figma design`}
                    className="w-full object-cover"
                    decoding="async"
                  />
                </div>
              ) : null}

              <div className="mt-8 grid gap-4 sm:grid-cols-3">
                <div className="rounded-2xl border border-neutral/20 bg-secondary p-5">
                  <h2 className="text-sm font-semibold text-accent">
                    {t("selectedProjects.labels.challenge")}
                  </h2>
                  <p className="mt-2 text-sm leading-6 text-neutral">{project.useCase.challenge}</p>
                </div>
                <div className="rounded-2xl border border-neutral/20 bg-secondary p-5">
                  <h2 className="text-sm font-semibold text-accent">
                    {t("selectedProjects.labels.approach")}
                  </h2>
                  <p className="mt-2 text-sm leading-6 text-neutral">{project.useCase.approach}</p>
                </div>
                <div className="rounded-2xl border border-neutral/20 bg-secondary p-5">
                  <h2 className="text-sm font-semibold text-accent">
                    {t("selectedProjects.labels.outcome")}
                  </h2>
                  <p className="mt-2 text-sm leading-6 text-neutral">{project.useCase.outcome}</p>
                </div>
              </div>
            </section>
          ) : null}

          {/* Highlights */}
          {project.highlights.length ? (
            <section>
              <SectionLabel>{t("caseStudy.highlights")}</SectionLabel>
              <ul className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {project.highlights.map((highlight) => (
                  <li
                    key={highlight}
                    className="flex gap-3 rounded-2xl border border-neutral/20 bg-secondary p-4 text-sm text-accent"
                  >
                    <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-neutral" />
                    <span>{highlight}</span>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}

          {/* Related services */}
          {relatedServices.length ? (
            <section>
              <SectionLabel>{t("caseStudy.relatedServices")}</SectionLabel>
              <div className="mt-4 flex flex-wrap gap-2">
                {relatedServices.map((service) => (
                  <Link
                    key={service.key}
                    to={service.href}
                    onClick={() =>
                      trackEvent("service_related_link_click", {
                        source: "case-study.relatedServices",
                        project_name: project.title,
                        service_key: service.key,
                      })}
                    className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-4 py-2 text-sm font-medium text-accent hover:bg-primary/70"
                  >
                    {service.title}
                  </Link>
                ))}
              </div>
            </section>
          ) : null}

          {/* CTA */}
          <section className="rounded-2xl border border-neutral-200 bg-secondary p-6 shadow-sm">
            <p className="text-sm font-semibold text-accent">{t("selectedProjects.cta.title")}</p>
            <p className="mt-1 text-sm text-neutral">{t("selectedProjects.cta.desc")}</p>
            <div className="mt-5 flex flex-wrap gap-3">
              <a
                href={project.href}
                target="_blank"
                rel="noreferrer"
                onClick={() =>
                  trackEvent("portfolio_click", {
                    source: "case-study.visit",
                    project_name: project.title,
                    target_url: project.href,
                  })}
                className="inline-flex items-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary hover:opacity-90"
              >
                {t("caseStudy.visitSite")}
              </a>
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="case-study.cta"
                className="inline-flex items-center rounded-2xl border border-neutral/25 bg-primary px-5 py-3 text-sm font-semibold text-accent hover:bg-primary/70"
              >
                {t("selectedProjects.labels.requestAudit")}
              </AuditRequestButton>
              <Link
                to={portfolioPath}
                className="inline-flex items-center rounded-2xl border border-neutral/25 bg-primary px-5 py-3 text-sm font-semibold text-accent hover:bg-primary/70"
              >
                {t("caseStudy.back")}
              </Link>
            </div>
          </section>

        </div>
      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC<object, PageContext> = ({ location, pageContext }) => {
  const { language, imageKey } = pageContext;
  const items = getLocaleValue<LivePortfolioProject[]>(language, "portfolio.live.items") || [];
  const project = items.find((p) => p.imageKey === imageKey);
  const title = project
    ? `${project.title} — Case Study | Juan Pablo Riano`
    : "Case Study | Juan Pablo Riano";
  const description = project?.useCase?.summary || project?.note || "";
  const slug = pageContext.slug;
  const pathname = `/${language}/portfolio/case-studies/${slug}/`;
  const alternates = [
    { hrefLang: "fr", href: `https://riano.ca/fr/portfolio/case-studies/${slug}/` },
    { hrefLang: "en", href: `https://riano.ca/en/portfolio/case-studies/${slug}/` },
    { hrefLang: "x-default", href: `https://riano.ca/fr/portfolio/case-studies/${slug}/` },
  ];

  return (
    <SEO
      data={info}
      title={title}
      description={description}
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
